// Created: 2026-11-15

/**
 * bin/sessions-under.mjs: the read side of the session stamp.
 *
 * Holds the instrument rules: read only (the DB bytes do not change), a zero
 * result is said out loud (stderr + exit 1), a DB before migration 006 is an
 * error and not an empty list.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { fileURLToPath } from 'node:url';

import { main } from '../../../bin/sessions-under.mjs';
import { openDb, __resetDbForTests } from '../../lib/session-registry.js';
import { sessionRegistrar } from '../../lifecycle/session-registrar.js';
import { computeRulesHash } from '../../lib/rules-hash.js';
import { NOOP_CTX } from '../../lib/context.js';
import type { HookInput } from '../../types.js';

const SCRIPT = fileURLToPath(new URL('../../../bin/sessions-under.mjs', import.meta.url));
const HASH_A = 'a'.repeat(8) + '1'.repeat(56);
const HASH_B = 'b'.repeat(64);

function sink(): { text: string; write(c: string): boolean } {
  return {
    text: '',
    write(c: string) {
      this.text += c;
      return true;
    },
  };
}

function sha(path: string): string {
  return createHash('sha256').update(readFileSync(path)).digest('hex');
}

describe('bin/sessions-under', () => {
  let work: string;
  let dbPath: string;
  let prevDb: string | undefined;
  let prevConfig: string | undefined;

  beforeEach(() => {
    work = mkdtempSync(join(tmpdir(), 'ork-under-'));
    dbPath = join(work, 'sessions.db');
    prevDb = process.env.ORK_SESSION_DB;
    prevConfig = process.env.CLAUDE_CONFIG_DIR;
    process.env.ORK_SESSION_DB = dbPath;
    __resetDbForTests();
  });

  afterEach(() => {
    __resetDbForTests();
    if (prevDb === undefined) delete process.env.ORK_SESSION_DB;
    else process.env.ORK_SESSION_DB = prevDb;
    if (prevConfig === undefined) delete process.env.CLAUDE_CONFIG_DIR;
    else process.env.CLAUDE_CONFIG_DIR = prevConfig;
    rmSync(work, { recursive: true, force: true });
  });

  /** Migrated DB with three sessions: two under HASH_A, one under HASH_B. */
  function seed(): void {
    const db = openDb();
    const ins = db.prepare(
      `INSERT INTO sessions (sid, pid, cwd, repo_hash, repo_path, worktree_path, branch, status,
         started_at, last_heartbeat, ended_at, ork_version, rules_hash)
       VALUES (?, 0, ?, 'h', ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    );
    ins.run('sid-a1-xxxxxxxx', '/r/one', '/r/one', null, 'main', 'ended', 1000, 1100, 1100, '10.13.0', HASH_A);
    ins.run('sid-a2-xxxxxxxx', '/r/two', '/r/two', '/r/two/.worktrees/x', 'fix/x', 'running', 2000, 2100, null, '10.13.0', HASH_A);
    ins.run('sid-b1-xxxxxxxx', '/r/three', '/r/three', null, 'feat/b', 'ended', 3000, 3100, 3100, '10.12.0', HASH_B);
    db.close();
    __resetDbForTests();
  }

  it('lists every session under a full rules_hash, oldest first, with branch and worktree', () => {
    seed();
    const out = sink();
    const err = sink();
    expect(main([HASH_A, '--db', dbPath], out, err)).toBe(0);
    const lines = out.text.trim().split('\n');
    expect(lines[0]).toMatch(/^started\tended\tstatus\trepo\tbranch\tworktree/);
    expect(lines).toHaveLength(4);
    expect(lines[1]).toContain('\tmain\t');
    expect(lines[1]).toContain('sid-a1-x');
    expect(lines[2]).toContain('\tfix/x\t/r/two/.worktrees/x\t');
    expect(out.text).not.toContain('feat/b');
    expect(lines[3]).toBe(`2 session(s) under ${HASH_A}`);
    expect(err.text).toBe('');
  });

  it('matches an 8+ hex prefix of rules_hash and an exact ork_version', () => {
    seed();
    const byPrefix = sink();
    expect(main([HASH_A.slice(0, 8), '--db', dbPath], byPrefix, sink())).toBe(0);
    expect(byPrefix.text).toContain('2 session(s)');

    const byVersion = sink();
    expect(main(['10.12.0', '--db', dbPath], byVersion, sink())).toBe(0);
    expect(byVersion.text).toContain('feat/b');
    expect(byVersion.text).toContain('1 session(s)');
  });

  it('says so and exits 1 when nothing matches, never an empty success', () => {
    seed();
    const out = sink();
    const err = sink();
    expect(main(['c'.repeat(64), '--db', dbPath], out, err)).toBe(1);
    expect(out.text).toBe('');
    expect(err.text).toContain('0 sessions match');
  });

  it('errors (exit 2) on a DB that predates migration 006 instead of returning none', () => {
    const old = join(work, 'old.db');
    const db = new DatabaseSync(old);
    db.exec('CREATE TABLE sessions (sid TEXT PRIMARY KEY, repo_path TEXT, branch TEXT, ork_version TEXT)');
    db.close();
    const err = sink();
    expect(main([HASH_A, '--db', old], sink(), err)).toBe(2);
    expect(err.text).toContain('predates migration 006');
  });

  it('errors (exit 2) on a missing DB and on bad usage', () => {
    const err = sink();
    expect(main([HASH_A, '--db', join(work, 'nope.db')], sink(), err)).toBe(2);
    expect(err.text).toContain('no session DB');
    expect(main([], sink(), sink())).toBe(2);
    expect(main(['a', 'b', '--db', dbPath], sink(), sink())).toBe(2);
  });

  it('is read only: the DB bytes are identical after a query', () => {
    seed();
    const before = sha(dbPath);
    expect(main([HASH_A, '--db', dbPath], sink(), sink())).toBe(0);
    expect(main(['c'.repeat(64), '--db', dbPath], sink(), sink())).toBe(1);
    expect(sha(dbPath)).toBe(before);
  });

  it('runs as a script and finds the session the registrar just stamped, with its branch', () => {
    const claudeDir = join(work, 'claude');
    mkdirSync(join(claudeDir, 'rules'), { recursive: true });
    writeFileSync(join(claudeDir, 'CLAUDE.md'), '# rules\n');
    writeFileSync(join(claudeDir, 'rules', 'visual-style.md'), '# style\n');
    process.env.CLAUDE_CONFIG_DIR = claudeDir;

    // A real git checkout so the row carries a real branch: this repo.
    const repoDir = fileURLToPath(new URL('../../../', import.meta.url));
    const branch = spawnSync('git', ['rev-parse', '--abbrev-ref', 'HEAD'], { cwd: repoDir, encoding: 'utf8' }).stdout.trim();
    expect(branch.length).toBeGreaterThan(0);

    sessionRegistrar(
      { hook_event: 'SessionStart', tool_name: '', session_id: 'sid-probe-0001', tool_input: {}, project_dir: repoDir } as HookInput,
      NOOP_CTX,
    );
    __resetDbForTests();

    const r = computeRulesHash(claudeDir);
    expect(r.ok).toBe(true);
    if (!r.ok) return;

    const run = spawnSync(process.execPath, [SCRIPT, r.hash, '--db', dbPath], { encoding: 'utf8' });
    expect(run.status).toBe(0);
    expect(run.stdout).toContain('sid-prob');
    expect(run.stdout).toContain(`\t${branch}\t`);
    expect(run.stdout).toContain('1 session(s) under');
  });
});
